/* ============================================================
   أطياب الجاسم (React) — التخطيط العام (MainLayout)

   هذا هو «MainScreen» في المشروع المرجعي: يُغلَّف مرة واحدة حول كل
   الصفحات التي يجب أن يظهر فيها الهيدر والفوتر، والصفحة النشطة تُرسم
   داخله عبر <Outlet /> — أي أنّ الراوتر هو من يبدّل الصفحات، لا App.

   المسؤوليات (كلّها عامة لا تخصّ صفحة بعينها):
     · <MainHeader />   الهيدر (وشريط الأدوات وقائمة الجوال)
     · <Outlet />        الصفحة الحالية التي اختارها الراوتر
     · <Footer />       الفوتر
     · <Toast />        التنبيه أسفل الشاشة (من ui.toast)
     · <StoryModal />   نافذة «قصة المنتج» عند اختيار منتج
     · تصفير التمرير + أصناف <body> عند كل تنقّل

   ★ لا حالة محليّة هنا إلا ما يخصّ الـDOM وحده (التمرير وأصناف
     <body>) — وكل شيء آخر يُقرأ من Redux أو من الراوتر.
   ============================================================ */

import { useEffect, useLayoutEffect, useRef } from "react";
import { Outlet, useLocation } from "react-router-dom";
import { useAppDispatch, useAppSelector } from "./redux/hooks.js";
import { uiActions } from "./redux/slices/uiSlice.js";
import MainPage from "./pages/MainPage.jsx";
import MainHeader from "./components/Headers/MainHeader.jsx";
import EventsBanner from "./components/Events/EventsBanner.jsx";
import Footer from "./components/Footers/Footer.jsx";
import StoryModal from "./components/Modals/StoryModal.jsx";
import { useUiTranslation } from "./uiTranslate.js";
import { dirOf } from "./i18n.js";
import { getStoreOpenStatus } from "./redux/slices/settingsSlice.js";

const TOAST_MS = 2600;

/* ------------------------------------------------------------
   التنبيه: يظهر ٢.٦ ثانية ثم يُخفي نفسه (نفس سلوك النسخة القديمة)
   ------------------------------------------------------------ */
function Toast() {
  const dispatch = useAppDispatch();
  const toast = useAppSelector(function (s) {
    return s.ui.toast;
  });

  useEffect(
    function () {
      if (!toast) return undefined;
      const id = window.setTimeout(function () {
        dispatch(uiActions.toastCleared());
      }, TOAST_MS);
      return function () {
        window.clearTimeout(id);
      };
    },
    [toast, dispatch]
  );

  return (
    <div className={"toast" + (toast ? " is-on" : "")} role="status" aria-live="polite">
      {toast ? toast.text : ""}
    </div>
  );
}

/* ------------------------------------------------------------
   التمرير إلى أعلى الصفحة عند كل تنقّل
   ★ حاويات التمرير حول التطبيق: حين يكون الموقع مُضمَّناً داخل حاوية
     تمرير (embed/iframe) فإن window لا يتحرّك أصلاً، ويبقى العميل في
     منتصف الصفحة بعد التنقّل — فنُصفّر كل حاوية قابلة للتمرير في سلسلة
     الآباء، لا window وحده.
   ------------------------------------------------------------ */
function useScrollReset(pathname, rootRef) {
  useLayoutEffect(
    function () {
      try {
        window.scrollTo(0, 0);
        const scroller = document.scrollingElement;
        if (scroller) scroller.scrollTop = 0;
        const html = document.documentElement;
        if (html) html.scrollTop = 0;
        if (document.body) document.body.scrollTop = 0;
        let el = (rootRef && rootRef.current) || document.body;
        while (el) {
          if (el.scrollTop) el.scrollTop = 0;
          el = el.parentElement;
        }
        try {
          if (window.parent && window.parent !== window) window.parent.scrollTo(0, 0);
        } catch (err) {
          /* إطار من أصل آخر: لا يمكن الوصول */
        }
      } catch (e) {
        /* بيئة بلا نافذة */
      }
    },
    [pathname, rootRef]
  );
}

export default function MainLayout() {
  const dispatch = useAppDispatch();
  const location = useLocation();
  const isHome = location.pathname === "/";
  const navOpen = useAppSelector(function (s) {
    return s.ui.mobileNavOpen;
  });
  const storyId = useAppSelector(function (s) {
    return s.ui.storyProductId;
  });
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });

  /* ★ مترجم الواجهة التلقائي + اتجاه الصفحة — بدونه تبقى كل النصوص
     المكتوبة عربيةً كما هي مهما بدّل العميل اللغة */
  useUiTranslation(language);

  useEffect(
    function () {
      try {
        document.documentElement.dir = dirOf(language);
        document.documentElement.lang = language === "en" ? "en" : "ar";
      } catch (e) {}
    },
    [language]
  );

  const mainRef = useRef(null);

  useScrollReset(location.pathname, mainRef);

  /* أصناف <body> — كما كانت النسخة القديمة تفعل */
  useEffect(
    function () {
      document.body.classList.toggle("nav-open", navOpen);
      document.body.classList.toggle("screen-open", !!storyId);
    },
    [navOpen, storyId]
  );

  /* إغلاق قائمة الجوال عند كل تنقّل */
  useEffect(
    function () {
      dispatch(uiActions.setMobileNav(false));
    },
    [location.pathname, dispatch]
  );

  /* ★ إشعار الأنيميشنات بتغيّر المسار: مشهد المبخرة 3D وعرض العطور 2D
     يستمعان لـatyab:route فيُعيدان القياس وقيادة حالة التشغيل (يتوقّفان
     وهما خارج الشاشة، ويعودان فوراً عند الرجوع إلى الرئيسية). */
  useEffect(
    function () {
      try {
        document.dispatchEvent(new CustomEvent("atyab:route", { detail: { route: location.pathname } }));
      } catch (e) {
        /* بيئة بلا CustomEvent */
      }
      /* ★ فحص الإغلاق عند الأحداث المهمة فقط: الرئيسية/السلة/الأمنيات */
      const p = location.pathname;
      if (p === "/" || p === "/cart" || p === "/wishlist") dispatch(getStoreOpenStatus());
    },
    [location.pathname, dispatch]
  );

  return (
    <>
      <MainHeader />

      <main className="main" id="main" ref={mainRef}>
        {/* ★ شريط الفعاليات: أسفل الهيدر تماماً (داخل main ليأخذ
            إزاحة الهيدر)، فوق كل المحتوى، لا يظهر إلا بوجود فعالية
            نشطة من GET /api/events/active */}
        <EventsBanner />
        {/* ★ الرئيسية تبقى مُركَّبة دائماً وتُخفى بـ[hidden] (انظر
            #main > .route-slot في Main.css) حتى لا يُعاد تحميل مشهد
            المبخرة 3D وعرض العطور 2D عند كل عودة إليها. لذلك لا يملك
            المسار "/" عنصراً في <Outlet> (انظر App.jsx). */}
        <div className="route-slot" hidden={!isHome}>
          <MainPage active={isHome} />
        </div>

        <Outlet />
      </main>

      <Footer />

      <Toast />

      {storyId ? <StoryModal /> : null}
    </>
  );
}
