/* ============================================================
   أطياب الجاسم (React) — الهيدر الصغير (الخط المعلوماتي)

   الشريط الباهت فوق الهيدر: «من نحن · شركات الشحن · طرق الدفع ·
   اللغة العربية · تحديد العملة · الامتثال القانوني».

   · الأزرار النصية روابط حقيقية إلى صفحاتها (hash) — الوجهة من
     ATYAB_PAGES في ملف البيانات (مصدر واحد لكل الروابط).
   · قائمتا اللغة والعملة منسدلتان، وتُرسل كل واحدة إلى طبقة ثابتة
     (.ib-layer) خارج الهيدر عند فتحها — فلا تُقتطع أبداً، كما في
     النسخة القديمة (src/infobar.js) — مع موضع محسوب من زرّها.
   · يُستعمل نفسه في الفوتر (flat) بلا خلفية.
   ============================================================ */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { Link } from "react-router-dom";
import { pathForPage } from "../../routes.js";
import { ATYAB_LANGUAGES, ATYAB_CURRENCIES, ATYAB_PAGES } from "../../data/appConfig.js";
import { useAppDispatch, useAppSelector } from "../../redux/hooks.js";
import { uiActions } from "../../redux/slices/uiSlice.js";
import { userActions } from "../../redux/slices/userSlice.js";
import { currencyMeta } from "../../redux/selectors.js";
import { t } from "../../i18n.js";
import { Icon, Flag } from "../Source/Icons.jsx";
import { CURRENCY_FLAG } from "../../constants/currencyFlags.js";

function shortEn(label) {
  return String(label == null ? "" : label).replace(/\s*\([^)]*\)\s*$/, "").trim();
}

function byKey(list, key) {
  for (let i = 0; i < list.length; i++) {
    if (String(list[i].key) === String(key)) return list[i];
  }
  return null;
}

/* هدف أي زر: من ATYAB_PAGES وإلا صفحة الصيانة — بصيغة مسار راوتر */
function pageTarget(key) {
  return pathForPage(key, ATYAB_PAGES);
}

/* ------------------------------------------------------------
   قائمة منسدلة عامة (تُرسم في طبقة ثابتة على <body>)
   ------------------------------------------------------------ */
function Dropdown(props) {
  const triggerRef = useRef(null);
  const menuRef = useRef(null);
  const [pos, setPos] = useState({ left: 0, top: 0, up: false });
  /* ★ فكّ خاصيتي الـeffect (open/onClose) خارج props — تبعيات دقيقة بلا كائن props كله. */
  const open = props.open;
  const onClose = props.onClose;

  /* موضع القائمة: تُحاذى مع زرّها، وتنقلب للأعلى إن ضاق الأسفل */
  const place = useCallback(function () {
    const trigger = triggerRef.current;
    const menu = menuRef.current;
    if (!trigger || !menu) return;
    const r = trigger.getBoundingClientRect();
    const mw = menu.offsetWidth || 232;
    const mh = menu.offsetHeight || 220;
    const pad = 8;
    const vw = window.innerWidth || document.documentElement.clientWidth;
    const vh = window.innerHeight || document.documentElement.clientHeight;
    const rtl = (getComputedStyle(document.documentElement).direction || "rtl") === "rtl";
    let left = rtl ? r.left : r.right - mw;
    if (left + mw > vw - pad) left = vw - pad - mw;
    if (left < pad) left = pad;
    let top = r.bottom + 7;
    let up = false;
    if (top + mh > vh - pad) {
      const above = r.top - 7 - mh;
      up = above >= pad;
      top = up ? above : Math.max(pad, vh - pad - mh);
    }
    setPos({ left: Math.round(left), top: Math.round(top), up: up });
  }, []);

  useEffect(
    function () {
      if (!open) return undefined;
      /* القياس الأول في إطار الرسم التالي لا في جسم الـeffect نفسه
         (setState متزامن داخل effect = رسم متتالٍ، وقاعدة React تمنعه) */
      const placeRaf = window.requestAnimationFrame(place);
      /* إعادة الحساب عند أي تمرير أو تغيير مقاس */
      const onScroll = function () {
        place();
      };
      window.addEventListener("scroll", onScroll, { passive: true, capture: true });
      window.addEventListener("resize", onScroll, { passive: true });
      return function () {
        if (placeRaf) window.cancelAnimationFrame(placeRaf);
        window.removeEventListener("scroll", onScroll, true);
        window.removeEventListener("resize", onScroll);
      };
    },
    [open, place]
  );

  useEffect(
    function () {
      if (!open) return undefined;
      function onDown(e) {
        if (triggerRef.current && triggerRef.current.contains(e.target)) return;
        if (menuRef.current && menuRef.current.contains(e.target)) return;
        onClose();
      }
      function onKey(e) {
        if (e.key === "Escape") onClose();
      }
      document.addEventListener("pointerdown", onDown);
      document.addEventListener("keydown", onKey);
      return function () {
        document.removeEventListener("pointerdown", onDown);
        document.removeEventListener("keydown", onKey);
      };
    },
    [open, onClose]
  );

  const label = props.label || "";
  return (
    <div className={"ib-widget " + (props.kind === "lang" ? "ib-lang" : "ib-curr")}>
      <button
        ref={triggerRef}
        className="ib-item ib-trigger"
        type="button"
        aria-haspopup="true"
        aria-expanded={props.open ? "true" : "false"}
        aria-label={label}
        onClick={function () {
          props.onToggle();
        }}
      >
        {props.kind === "lang" ? (
          <span className="ib-flag">
            <Flag code={props.flag} />
          </span>
        ) : (
          <span className="ib-cur-sym">{props.symbol}</span>
        )}
        <span className="ib-item-label">{props.currentLabel}</span>
        <Icon name="chev" className="ib-caret" strokeWidth={2.1} />
      </button>

      {props.open
        ? createPortal(
            <div className="ib-layer">
              <ul
                className="ib-menu"
                role="menu"
                ref={menuRef}
                style={{ left: pos.left + "px", top: pos.top + "px" }}
              >
                {props.items.map(function (item) {
                  const on = item.active;
                  return (
                    <li key={item.key} role="none">
                      <button
                        className="ib-menu-item"
                        type="button"
                        role="menuitemradio"
                        aria-checked={on ? "true" : "false"}
                        onClick={function () {
                          props.onPick(item.key);
                        }}
                      >
                        <span className="ib-menu-flag">
                          <Flag code={item.flag} />
                        </span>
                        <span className="ib-menu-name">
                          {item.name}
                          {item.hint ? <span className="ib-menu-hint">{item.hint}</span> : null}
                        </span>
                        <Icon name="check" className="ib-check" strokeWidth={2.4} />
                      </button>
                    </li>
                  );
                })}
              </ul>
            </div>,
            document.body
          )
        : null}
    </div>
  );
}

/* ------------------------------------------------------------
   الخط المعلوماتي
   ------------------------------------------------------------ */
export default function SmallHeader(props) {
  const dispatch = useAppDispatch();
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const currency = useAppSelector(function (s) {
    return s.user.profile.currency;
  });
  const [open, setOpen] = useState(null); /* "lang" | "curr" | null */

  const isEn = language === "en";
  /* ★ ثوابت الوحدات — تُحسب مرة واحدة (ATYAB_* ثوابت وحدات؛ الـ|| للدفاع فقط). */
  const languages = useMemo(function () { return ATYAB_LANGUAGES || []; }, []);
  const currencies = useMemo(function () { return ATYAB_CURRENCIES || []; }, []);

  const langMeta = byKey(languages, language) || languages[0] || { label: "العربية", flag: "sa" };
  const currMeta = currencyMeta(currency);

  const langItems = useMemo(
    function () {
      return languages.map(function (l) {
        return {
          key: l.key,
          name: isEn ? l.labelEn || l.label : l.label,
          flag: l.flag,
          active: l.key === language
        };
      });
    },
    [languages, isEn, language]
  );

  const currItems = useMemo(
    function () {
      return currencies.map(function (c) {
        return {
          key: c.key,
          name: isEn ? shortEn(c.labelEn || c.label) : c.short || c.label,
          hint: c.symbol + (c.symbolEn && c.symbolEn !== c.symbol ? " · " + c.symbolEn : ""),
          flag: CURRENCY_FLAG[c.key] || "sa",
          active: c.key === currency
        };
      });
    },
    [currencies, isEn, currency]
  );

  /* شعار الأزرار النصية */
  const LINKS = [
    { key: "about", icon: "store", label: "من نحن", i18n: "bar.about" },
    { key: "shippingInfo", icon: "truck", label: "معلومات شركات الشحن", i18n: "bar.shipping" },
    { key: "payments", icon: "card", label: "طرق الدفع المتاحة", i18n: "bar.payments" }
  ];

  function pickLanguage(key) {
    dispatch(uiActions.setLanguage(key));
    dispatch(userActions.setProfile({ language: key }));
    const meta = byKey(languages, key);
    dispatch(
      uiActions.toastShown(
        t(language, "toast.lang", "تم تغيير لغة الواجهة إلى") + " " + (key === "ar" ? (meta && meta.label) || "العربية" : "English")
      )
    );
    setOpen(null);
  }

  function pickCurrency(key) {
    dispatch(userActions.setCurrency(key));
    const meta = byKey(currencies, key);
    dispatch(
      uiActions.toastShown(
        t(language, "toast.currency", "تم تغيير العملة إلى") +
          " " +
          (meta ? (isEn ? shortEn(meta.labelEn || meta.label) : meta.short || meta.label) : key)
      )
    );
    setOpen(null);
  }

  return (
    <div className={"infobar" + (props && props.flat ? " infobar--flat" : "")}>
      <div className="container infobar-inner">
        {LINKS.map(function (link) {
          return (
            <Link
              key={link.key}
              className="ib-item"
              to={pageTarget(link.key)}
              data-page={link.key}
            >
              <Icon name={link.icon} strokeWidth={1.8} />
              <span>{isEn ? t("en", link.i18n, link.label) : link.label}</span>
            </Link>
          );
        })}

        <Dropdown
          kind="lang"
          open={open === "lang"}
          flag={langMeta.flag || "sa"}
          label={t(language, "a11y.langMenu", "اختر اللغة")}
          currentLabel={
            isEn ? langMeta.labelEn || langMeta.label : langMeta.widget || langMeta.label
          }
          items={langItems}
          onToggle={function () {
            setOpen(open === "lang" ? null : "lang");
          }}
          onClose={function () {
            setOpen(null);
          }}
          onPick={pickLanguage}
        />

        <Dropdown
          kind="curr"
          open={open === "curr"}
          symbol={isEn ? currMeta.symbolEn || currMeta.symbol : currMeta.symbol}
          label={t(language, "a11y.currencyMenu", "اختر العملة")}
          currentLabel={isEn ? shortEn(currMeta.labelEn || currMeta.label) : currMeta.short || currMeta.label}
          items={currItems}
          onToggle={function () {
            setOpen(open === "curr" ? null : "curr");
          }}
          onClose={function () {
            setOpen(null);
          }}
          onPick={pickCurrency}
        />

        <Link className="ib-item" to={pageTarget("legal")} data-page="legal">
          <Icon name="shield" strokeWidth={1.8} />
          <span>{isEn ? t("en", "bar.legal", "الامتثال القانوني") : "الامتثال القانوني"}</span>
        </Link>
      </div>
    </div>
  );
}
