import { useMemo } from "react";
import { createAsyncThunk, createSlice } from "@reduxjs/toolkit";
import { fetchGeoLists, findCountryByRegion, countryIdOfRow } from "../../api/customers.js";
import { citiesOfCountry } from "../../data/appConfig.js";
import { cityAr } from "../../data/cityNames.js";
import { useAppSelector } from "../hooks.js";
import { KEYS, readJSON, writeJSON } from "../persist.js";

const GEO_CACHE_TTL = 24 * 3600 * 1000;

function readGeoCache() {
  const c = readJSON(KEYS.geo, null);
  if (!c || !Array.isArray(c.cities) || !c.at) return null;
  if (Date.now() - Number(c.at) > GEO_CACHE_TTL) return null;
  return c;
}

export const loadGeo = createAsyncThunk("geo/load", async function (_, thunk) {
  const g = thunk.getState().geo;
  if (g && (g.status === "loading" || (g.status === "ready" && g.cities.length))) {
    return { countries: g.countries, cities: g.cities, cached: true };
  }
  const data = await fetchGeoLists();
  return { countries: data.countries, cities: data.cities, cached: false };
});

const cached = readGeoCache();

const slice = createSlice({
  name: "geo",
  initialState: {
    countries: (cached && cached.countries) || [],
    cities: (cached && cached.cities) || [],
    status: cached ? "ready" : "idle",
    error: ""
  },
  reducers: {},
  extraReducers: function (builder) {
    builder
      .addCase(loadGeo.pending, function (state) {
        if (state.status === "idle") state.status = "loading";
      })
      .addCase(loadGeo.fulfilled, function (state, action) {
        if (action.payload.cached) {
          state.status = "ready";
          return;
        }
        state.countries = action.payload.countries || [];
        state.cities = action.payload.cities || [];
        state.status = "ready";
        writeJSON(KEYS.geo, { at: Date.now(), countries: state.countries, cities: state.cities });
      })
      .addCase(loadGeo.rejected, function (state) {
        state.status = state.cities.length ? "ready" : "error";
      });
  }
});

export const geoReducer = slice.reducer;

/* خيارات مدن دولة: من الخادم (مترجمة) أولاً ثم الثابتة — null إن لا تغطية */
export function serverCityOptions(geo, regionKey, lang) {
  const rows = (geo && geo.cities) || [];
  if (!rows.length) return null;
  const hit = findCountryByRegion(geo.countries || [], regionKey);
  if (!hit) return null;
  const cid = countryIdOfRow(hit);
  if (cid == null) return null;
  const mine = rows.filter(function (o) {
    const v = o.countryId != null ? o.countryId : o.CountryId;
    return Number(v) === Number(cid);
  });
  if (!mine.length) return null;
  const out = mine.map(function (o) {
    const en = String(o.cityName || o.name || "");
    const ar = cityAr(en);
    return { key: ar, label: lang === "en" ? en : ar };
  });
  const have = {};
  out.forEach(function (o) { have[o.key] = 1; });
  citiesOfCountry(regionKey, lang).forEach(function (o) {
    if (!have[o.key]) out.push(o);
  });
  return out;
}

/* خطّاف القائمة المدمجة (خادم + ثابت كاحتياط) */
export function useCityOptions(regionKey, lang) {
  const geo = useAppSelector(function (s) { return s.geo; });
  return useMemo(
    function () {
      return serverCityOptions(geo, regionKey, lang) || citiesOfCountry(regionKey, lang);
    },
    [geo, regionKey, lang]
  );
}
