/* صفحة العروض — شاشة كاملة لكل عرض، بلا صور */
import "./Skeletons.css";

export default function OfferSkeleton(props) {
  const count = Math.max(1, Math.min(4, Number(props.count) || 2));
  const items = [];
  for (let i = 0; i < count; i++) {
    items.push(
      <div className="sk-offer" key={i} aria-hidden="true">
        <div style={{ display: "grid", gap: 12, alignContent: "start" }}>
          <span className="sk-block sk-offer-title" />
          <span className="sk-block sk-line" />
          <span className="sk-block sk-line short" />
          <span className="sk-block sk-line" />
          <span className="sk-block sk-btn" style={{ width: "60%" }} />
        </div>
        <div className="sk-block sk-offer-media" />
      </div>
    );
  }
  return (
    <div role="status" aria-live="polite" aria-label="جارٍ تحميل العروض">
      {items}
    </div>
  );
}
