function termsBody() {
  const ar = [TERMS.intro.ar];
  const en = [TERMS.intro.en];
  TERMS.clauses.forEach(function (c) {
    ar.push(c.n + ". " + c.title.ar + " — " + c.body.ar);
    en.push(c.n + ". " + c.title.en + " — " + c.body.en);
  });
  ar.push(TERMS.contact.ar);
  en.push(TERMS.contact.en);
  return { ar: ar.join("\n\n"), en: en.join("\n\n") };
}

