/* رقم واتساب المالك (بصيغة دولية بلا +) — زر «احجز الآن» عند نفاد المنتج */
const OWNER_WHATSAPP = "971547973003";

/* رابط حجز واتساب برسالة تلقائية جذابة عن المنتج — الرقم من /api/store/settings، والثابت احتياط */
function whatsappBookUrl(product, overrideDigits) {
  const name = (product && (product.name || product.nameEn)) || "هذا المنتج";
  const id = product && product.id != null ? product.id : "";
  const price = product && Number(product.price) > 0 ? product.price : null;
  const lines = [
    "السلام عليكم 🌸",
    "أريد حجز: *" + name + "*" + (id !== "" ? " (رقم المنتج " + id + ")" : ""),
    price != null ? "السعر المعروض: " + price + " د.إ" : null,
    "هل ما زال متوفراً؟ — متجر أطياب الجاسم"
  ].filter(Boolean);
  const digits = String(overrideDigits || "").replace(/\D/g, "") || OWNER_WHATSAPP;
  return "https://wa.me/" + digits + "?text=" + encodeURIComponent(lines.join("\n"));
}

